SELECT *, SUM(pressure) OVER (PARTITION BY device_code ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) pressure_sum_2h, AVG(temp_c) OVER w_recent temp_c_avg_2_prior, SUM(temp_c) OVER (PARTITION BY device_code ORDER BY humidity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_temp_c, NTILE(10) OVER w_hist status_bits_bucket, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY status_bits DESC, id) seq_no FROM device_readings WINDOW w_recent AS (ORDER BY humidity, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING), w_hist AS (PARTITION BY YEAR(reading_ts), device_code ORDER BY status_bits DESC, id);
